class Solution {
public:
    int subarraysDivByK(vector<int>& a, int k) {
        vector<int> cnt(k, 0);
        cnt[0] = 1;
        int run = 0, ans = 0;
        for (int x : a) {
            run = ((run + x) % k + k) % k;
            ans += cnt[run]++;
        }
        return ans;
    }
};
