class Solution {
public:
    int numSubarraysWithSum(vector<int>& a, int goal) {
        vector<int> cnt(a.size() + 1, 0);       // prefix sums of a 0/1 array are in [0, n]
        cnt[0] = 1;
        int run = 0, ans = 0;
        for (int x : a) {
            run += x;
            if (run - goal >= 0) ans += cnt[run - goal];
            cnt[run]++;
        }
        return ans;
    }
};
